package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The claims' comments, each oldest first. */
@Repository
public class ClaimCommentRepository {

    private final JdbcTemplate jdbc;

    public ClaimCommentRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void append(String sheetId, ClaimComment comment) {
        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, comment_date, text) VALUES (?, ?, ?, ?, ?)",
                sheetId, comment.claimId(), comment.by(), Date.valueOf(comment.date()), comment.text());
    }

    /** The sheet's comments by claim id, each oldest first. */
    public Map<Long, List<ClaimComment>> findAll(String sheetId) {
        Map<Long, List<ClaimComment>> comments = new LinkedHashMap<>();
        jdbc.query("SELECT claim_id, by_user, comment_date, text FROM claim_comment WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    ClaimComment comment = new ClaimComment(rs.getLong("claim_id"), rs.getString("by_user"),
                            rs.getDate("comment_date").toLocalDate(), rs.getString("text"));
                    comments.computeIfAbsent(comment.claimId(), (k) -> new ArrayList<>()).add(comment);
                }, sheetId);
        return comments;
    }

    /** The claim's comments, oldest first. */
    public List<ClaimComment> find(String sheetId, long claimId) {
        return findAll(sheetId).getOrDefault(claimId, List.of());
    }
}
package net.officefloor.hq.app.claim;

/** What a comment submits: its text (null or blank: none typed). */
public record CommentRequest(String text) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the comment's body once, publishing its text; refuses (400) an empty comment. */
public class ValidateCommentRequest {
    public void validate(@RequestBody CommentRequest request, Out<CommentText> comment) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text().trim();
        if (text.isEmpty()) {
            throw new InvalidClaimException("Type a comment.");
        }
        comment.set(new CommentText(text));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuses (400) an edit of any claim that is not a DRAFT: an open claim is changed by voiding it and adding another. */
public class CheckClaimDraft {
    public void check(@Val Claim claim) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) any change to a claim whose due-by falls inside a closed period (its period is the one containing its due-by). */
public class CheckClaimPeriodOpen {
    public void check(@Val Claim claim, PeriodRepository periods) throws InvalidClaimException {
        Period closed = periods.closedOn(claim.sheetId(), claim.dueBy());
        if (closed != null) {
            throw new InvalidClaimException("The claim is due by " + claim.dueBy() + ", in the closed period " + closed.name() + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Refuses (400) an edit of a claim another user has locked by opening its editor. */
public class CheckClaimNotLocked {
    public void check(@Val Claim claim, @RequestParam("user") String user, ClaimLockRepository locks)
            throws InvalidClaimException {
        String holder = locks.lockedBy(claim.sheetId(), claim.id());
        if (holder != null && !holder.equals(user)) {
            throw new InvalidClaimException("The claim is being edited by " + holder + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the user as the claim's last editor (four eyes: they cannot then settle or approve it). */
public class MarkClaimEdited {
    public void mark(@Val Claim claim, @RequestParam("user") String user, ClaimRepository claims) {
        claims.markEdited(claim.sheetId(), claim.id(), user);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just edited, with its person's name; runs only once the edit has passed every rule. */
public class AuditClaimEdited {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_EDITED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()));
    }
}

